const html = items[0].json || items[0].binary?.data;
const text = typeof html === 'string' ? html.toLowerCase() : JSON.stringify(html).toLowerCase();

let score = 0;
const reasons = [];

if (text.includes('casino') || text.includes('viagra') || text.includes('loan')) { score += 3; reasons.push('Spam keywords detected'); }
if (text.includes('<iframe')) { score += 1; reasons.push('Contains iframes'); }
if (text.includes('http://')) { score += 1; reasons.push('Insecure http links'); }

return [{ json: { riskScore: score, reasons } }];
